/bin/zsh -lc "node --input-type=module <<'JS'
import fs from 'node:fs';
import assert from 'node:assert/strict';
import yaml from 'js-yaml';
const path = 'blog/post/lab/Fixture_Cache.md';
const article = fs.readFileSync(path, 'utf8');
const [, header, body] = article.match(/"'^---'"\\n([\\s\\S]*?)\\n---\\n([\\s\\S]*)"'$/);
const meta = yaml.load(header);
assert.equal(meta.title, '"'Fixture Cache');
assert.equal(meta.description, '認識 cache 的基本用途、命中與資料更新。');
assert.equal(meta.thumbnail, '/assets/fixture.svg');
assert.equal(meta.createdTime, '2026-10-24T17:56:39+08:00');
assert.ok(fs.statSync('blog/public' + meta.thumbnail).isFile());
assert.ok(fs.statSync('blog/public/assets/post_lab_Fixture_Cache').isDirectory());
assert.equal(body.replace(/"'^'"\\s*# Fixture Cache\\s*/u, '').split('。').filter(s => s.trim()).length, 3);
console.log('文章檢查通過：frontmatter、CLI 建立時間、三句正文、縮圖與資源資料夾。');
console.log(article);
JS"

