/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
import stat
key = 'rain-cache'
assert key and key not in ('.', '..') and '/' not in key and '\\\\' not in key
root = Path.cwd()
for p in (root / '.proj.writing', root / '.proj.writing' / key):
    try:
        s = p.lstat()
    except FileNotFoundError:
        print(f'MISSING {p.relative_to(root)}')
        continue
    print(f'{p.relative_to(root)}: directory={stat.S_ISDIR(s.st_mode)} symlink={stat.S_ISLNK(s.st_mode)}')
    if not stat.S_ISDIR(s.st_mode) or stat.S_ISLNK(s.st_mode):
        raise SystemExit('Unsafe workspace destination')
    if p.name == key:
        for f in sorted(p.iterdir()):
            s = f.lstat()
            print(f'{f.name}: regular={stat.S_ISREG(s.st_mode)} executable={bool(s.st_mode & 0o111)} symlink={stat.S_ISLNK(s.st_mode)}')
            if f.name in ('PROJECT.md', 'GLOSSARY.md', 'CONTEXT.md'):
                if not stat.S_ISREG(s.st_mode) or s.st_mode & 0o111:
                    raise SystemExit('Unsafe note destination')
                print(f.read_text())
PY"
